<template>



                 <div class="modal fade mymodal" id="general-statements-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel"> Bulk Fuel Stetements</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>
<div class="modal-body" >
    
    <div class="row layout-top-spacing">
              <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                  <div v-if="loading" v-html="tableShimmer()"></div>
                  <div v-else class="custom-table table3">
                    <v-client-table
                      :data="projectExpenseItems"
                      :columns="projectExpenseItemsColumns"
                      :options="table_option"
                    >
                                                        <template #ratio="props">
    <div class="">
      {{ fuelRatio(props.row.final_reading, props.row.initial_reading,  props.row.type, props.row.unformatedQty) }}
    </div>
  </template>
                    </v-client-table>
                  </div>
                </div>
              </div>
            </div>




      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>

      </div>

    </div>
  </div>

</div>






</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

   const fuelRatio = inject('fuelRatio')


const formatNumber = inject("formatNumber");
const formatRate = inject("formatRate");
const showError = inject('showError')
const tableShimmer = inject('tableShimmer')


const loading = ref(false)

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 51, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo", "name", "short_name", "status"],
  sortIcon: {
    base: "sort-icon-none",
    up: "sort-icon-asc",
    down: "sort-icon-desc",
  },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});


const projectExpenseItemsColumns = ref(["sno", "task", "quantity", "initial", "final", "ratio",  "date", "actions"]);

const projectExpenseItems = ref([]);
const getProjectExpenseItems = async () => {
  loading.value = true
  try {
    const response = await axiosInstance.get(`project-expense-items?entry_id=${props.entryId}`);
    projectExpenseItems.value = response.data.map((item, index) => ({
      ...item,
      sno: index + 1,
      date: item.date || "--",
       type:item.item.asset_class,
task: `${item.item?.code
    ? `${item.item.code}${item.parent?.name ? `  ${item.parent.name}` : ""}`
    : item.item?.name || ""
}${item.description ? `   ${item.description}` : ""}${item.work_target ? `   ${formatNumber(item.work_target)} ${item.work_unit || ""} Target` : ""}` || "--",
      rate: formatRate(item.rate || "-"),
      originalDescription:item.description,
      unformatedRate: item.rate,          // NEW
      unformatedQty: item.quantity,       // NEW
      initial: formatNumber(item.initial_reading ),
      target: formatNumber(item.work_target || 0)  + (item.work_unit || ""),
      final: formatNumber(item.final_reading ),
      diff: Number(item.final_reading) === 0
  ? formatNumber(0)
  : formatNumber(Number(item.final_reading) - Number(item.initial_reading)),

      cost: formatRate((item.rate || 0) * (item.quantity || 0)),
      name: item.item?.code ? `${item.item.code} - ${item.parent?.name || ""}` : item.item?.name || "-",
      unit: item.unit?.short_name || "-",
      quantity: formatNumber(item.quantity || "-"),
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  }finally{
    loading.value = false
  }
};

const props = defineProps({
  entryId: { type: [String, Number], required: true }
});


watch(() => props.entryId, (id) => {
  if (id) getProjectExpenseItems();
});

</script>




